if (raw == null) return null
def s = raw.toString().trim()
if (s.isEmpty()) return null
// Preposiciones/articulos espanoles que van en minuscula salvo posicion inicial
def preposiciones = ['de','del','la','las','los','y','e','a','al','en','con','o'] as Set
// Title Case por palabra
def titled = s.toLowerCase().split(' ').toList().findAll { it }.withIndex().collect { word, i ->
    (i == 0 || !(word in preposiciones)) ? word.capitalize() : word
}.join(' ')
// NFC + colapso de espacios
def out = java.text.Normalizer.normalize(titled, java.text.Normalizer.Form.NFC).replaceAll('\\s+', ' ').trim()
return out ?: null

if (raw == null) return null
def s = java.text.Normalizer.normalize(raw.toString(), java.text.Normalizer.Form.NFC).trim()
if (s.isEmpty()) return null
def particles = ['de','del','la','las','los','y'] as Set
def capWord = { String w ->
    def sb = new StringBuilder()
    boolean up = true
    for (char ch : w.toCharArray()) {
        sb.append(up ? Character.toUpperCase(ch) : ch)
        up = (ch == (char) 45 || ch == (char) 39 || ch == (char) 0x2019)
    }
    sb.toString()
}
def words = s.toLowerCase(new Locale('es', 'PE')).split(/\s+/).toList().findAll { it }
def out = []
words.eachWithIndex { w, i -> out.add((i > 0 && particles.contains(w)) ? w : capWord(w)) }
def r = out.join(' ').trim()
return r ?: null
